"""Templates + writer for `atf-eval init` -- generates a starter adapter and
a matching golden dataset so a new user gets a working `atf-eval run` on the
first try, then edits both files to point at their real agent.
"""
from __future__ import annotations

from pathlib import Path

ADAPTER_TEMPLATE = '''\
"""Starter TrajectoryAgent adapter -- generated by `atf-eval init`.

Out of the box this returns canned data matching golden_dataset.jsonl, so
`atf-eval run` works immediately as a smoke test. Replace the two TODOs
below with a real call to your agent and a real translation of its trace.

Full field reference: https://github.com/janarddansarkar/atf-eval#readme
"""
from __future__ import annotations

from atf_eval.normalized import (
    NormalizedNode,
    NormalizedTurn,
    Outcome,
    Routing,
    StateChange,
    ToolCall,
)


class MyAgentAdapter:
    def run_turn(self, conversation_id, turn_id, user_input, history) -> NormalizedTurn:
        # TODO 1: call your real agent instead of the canned response below.
        # raw = my_agent.invoke(user_input, history=history)

        # TODO 2: replace this hardcoded trajectory with one built from `raw`.
        # Every NormalizedTurn field except conversation_id/turn_id is
        # optional -- only populate what your agent actually exposes; the
        # matching metric group reports N/A (not a penalty) for the rest.
        if turn_id == 1:
            return NormalizedTurn(
                conversation_id=conversation_id,
                turn_id=turn_id,
                nodes=[
                    NormalizedNode(node_id="classify_intent"),
                    NormalizedNode(
                        node_id="check_order_status",
                        state_changes=[StateChange(key="order_status_checked", old=False, new=True)],
                    ),
                ],
                state_changes=[StateChange(key="order_status_checked", old=False, new=True)],
                tool_calls=[ToolCall(tool_id="lookup_order", status="success")],
                routing=Routing(path="investigate", target="support_agent"),
                response="Let me check on that order for you.",
            )

        return NormalizedTurn(
            conversation_id=conversation_id,
            turn_id=turn_id,
            nodes=[NormalizedNode(node_id="confirm_outcome")],
            routing=Routing(path="confirm", target="customer"),
            outcome=Outcome(id="refund_issued", attributes={"amount": 25}),
            response="I've issued a refund of 25.",
        )
'''

GOLDEN_DATASET_TEMPLATE = (
    '{"conversation_id": "example_conv_01", "turn_id": 1, '
    '"user_input": "My package hasn\'t arrived yet.", '
    '"nodes": [{"node_id": "classify_intent"}, {"node_id": "check_order_status"}], '
    '"state_changes": [{"key": "order_status_checked", "old": false, "new": true, '
    '"node_id": "check_order_status"}], '
    '"tool_calls": [{"tool_id": "lookup_order", "arguments": {}}], '
    '"routing": {"path": "investigate", "target": "support_agent"}, '
    '"outcome": null, "metadata": {}}\n'
    '{"conversation_id": "example_conv_01", "turn_id": 2, '
    '"user_input": "Yes please refund me.", '
    '"nodes": [{"node_id": "confirm_outcome"}], '
    '"state_changes": [], "tool_calls": [], '
    '"routing": {"path": "confirm", "target": "customer"}, '
    '"outcome": {"id": "refund_issued", "attributes": {"amount": 25}, '
    '"required_conditions": ["amount"]}, "metadata": {}}\n'
)

README_TEMPLATE = """\
# Getting started

Generated by `atf-eval init`. Two files, both runnable as-is:

- `golden_dataset.jsonl` -- the expected trajectory
- `adapter.py` -- returns canned data matching it, so this works immediately

## 1. Try it now (no changes needed)

```bash
pip install git+https://github.com/janarddansarkar/atf-eval.git
atf-eval run --dataset golden_dataset.jsonl --adapter adapter:MyAgentAdapter --no-routing-judge
```

You should see `ATF score: 1.000` -- that confirms the framework itself works before you
touch anything.

## 2. Wire up your real agent

Edit `adapter.py`'s two TODOs to call your actual agent and translate its real trace, and
edit `golden_dataset.jsonl` to describe what your agent is actually expected to do on the
conversations you care about. Then rerun the command above.

Only `conversation_id`/`turn_id` are required per turn -- leave out any dimension your
agent doesn't expose (state, tools, routing, outcome) and that metric group correctly
reports N/A instead of being penalized.

Full docs: https://github.com/janarddansarkar/atf-eval
"""

_FILES = {
    "adapter.py": ADAPTER_TEMPLATE,
    "golden_dataset.jsonl": GOLDEN_DATASET_TEMPLATE,
    "README.md": README_TEMPLATE,
}


def write_scaffold(output_dir: Path, force: bool = False) -> list[Path]:
    """Writes adapter.py, golden_dataset.jsonl, README.md into output_dir.
    Refuses to overwrite existing files unless force=True. Returns the list
    of paths written."""
    output_dir.mkdir(parents=True, exist_ok=True)

    if not force:
        existing = [name for name in _FILES if (output_dir / name).exists()]
        if existing:
            raise FileExistsError(
                f"refusing to overwrite existing file(s): {', '.join(existing)} "
                "(pass --force to overwrite)"
            )

    written = []
    for name, content in _FILES.items():
        path = output_dir / name
        path.write_text(content, encoding="utf-8")
        written.append(path)
    return written
